const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'A' },
      { kind: 'text', payload: 'B' },
      { kind: 'text', payload: '1:1' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '1' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var y = Math.round(H * 0.58);
    var x0 = Math.round(W * 0.10);
    var x1 = Math.round(W * 0.90);
    var xm = Math.round((x0 + x1) / 2);
    var tick = Math.max(8, Math.round(H * 0.055));
    var qa = Math.round((x0 + xm) / 2);
    var qb = Math.round((xm + x1) / 2);
    var ink = '#26354a';

    var paths = [
      { id: 'segA', commands: visualSdk.polyline([[x0, y], [xm, y]]) },
      { id: 'segB', commands: visualSdk.polyline([[xm, y], [x1, y]]) },
      { id: 'endA', commands: visualSdk.polyline([[x0, y - tick], [x0, y + tick]]) },
      { id: 'mid', commands: visualSdk.polyline([[xm, y - tick], [xm, y + tick]]) },
      { id: 'endB', commands: visualSdk.polyline([[x1, y - tick], [x1, y + tick]]) },
      { id: 'markA', commands: visualSdk.polyline([[qa, y - tick], [qa, y + tick]]) },
      { id: 'markB', commands: visualSdk.polyline([[qb, y - tick], [qb, y + tick]]) }
    ];

    var children = [];
    var i;
    for (i = 0; i < paths.length; i++) {
      children.push({
        type: 'path',
        pathId: paths[i].id,
        fill: 'none',
        stroke: { width: 2, color: ink }
      });
    }

    children.push({
      type: 'label', contentId: 'c0', anchor: { x: x0, y: y + tick + 8 },
      hAlign: 'center', vAlign: 'top', color: ink
    });
    children.push({
      type: 'label', contentId: 'c1', anchor: { x: x1, y: y + tick + 8 },
      hAlign: 'center', vAlign: 'top', color: ink
    });
    children.push({
      type: 'label', contentId: 'c2', anchor: { x: xm, y: y - tick - 12 },
      hAlign: 'center', vAlign: 'bottom', color: ink
    });
    children.push({
      type: 'label', contentId: 'c3', anchor: { x: qa, y: y + tick + 8 },
      hAlign: 'center', vAlign: 'top', color: ink
    });
    children.push({
      type: 'label', contentId: 'c4', anchor: { x: qb, y: y + tick + 8 },
      hAlign: 'center', vAlign: 'top', color: ink
    });

    return {
      schemaVersion: 1,
      sceneId: 'segment-1to1',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
